      "candidate": {
        "family": "kzm_ei_scaling",
        "title": "Incompressible kinetic energy scaling with quench duration in a Kibble-Zurek quench",
        "claim": "The incompressible kinetic energy at equilibration time follows a power-law dependence on quench duration, with the amplitude and exponent depending on the temperature regime.",
        "source": {
          "citation": "Seong-Ho Shinn, Spontaneous Quantum Turbulence in a Newborn Bose-Einstein Condensate via the Kibble-Zurek Mechanism, Physical Review Letters (2026), DOI:10.1103/b16v-hwp2",
